window.ALLYSPAN_LOCALE={"language":"es","routes":["/","/about/allyspan-and-logo/","/about/our-mission/","/about/our-support/","/about/connect/","/resources/introduction-to-classroom-studio/","/resources/qr-studio/","/showcase/publications/","/showcase/how-to-publish/","/showcase/submit-your-work/","/showcase/submission-privacy/"],"messages":{"Allyspan | Community Support, Learning and Publications":"Allyspan | Apoyo comunitario, aprendizaje y publicaciones","Skip to content":"Saltar al contenido","Allyspan":"Allyspan","About Us":"Quiénes somos","Programs":"Programas","Resources":"Recursos","Students Initiative":"Iniciativa estudiantil","Showcase":"Publicaciones y proyectos","Support":"Apoyo","Allyspan & Logo":"Allyspan y su logotipo","Our Mission":"Nuestra misión","Our Support":"Nuestro apoyo","Connect":"Contacto","Introduction to Classroom Studio":"Introducción a Classroom Studio","A basic guide for teachers and learners":"Una guía básica para docentes y estudiantes","Classroom Studio":"Classroom Studio","Thoughtful presentations for multilingual classrooms":"Presentaciones pensadas para aulas multilingües","Allyspan QR Studio":"Allyspan QR Studio","Create and download a free QR code for your link":"Crea y descarga gratis un código QR para tu enlace","Apply as Volunteer":"Participa como voluntario","Coming soon":"Próximamente","Apply as Intern":"Solicita una pasantía","How to Publish Your Work":"Cómo publicar tu trabajo","Community Awareness Publications":"Publicaciones de concienciación comunitaria","English":"English","More languages coming soon":"Más idiomas próximamente","Subscribe":"Suscribirse","Website subscriptions are coming soon":"Las suscripciones al sitio web estarán disponibles próximamente","Teachers can already subscribe to Classroom Studio updates in their Studio account settings":"Los docentes ya pueden suscribirse a las novedades de Classroom Studio desde la configuración de su cuenta de Studio","Understanding grows.":"Crece la comprensión.","Communities move forward.":"Las comunidades avanzan.","Allyspan brings together community support, accessible learning and thoughtful public discussion. We make room for people’s experiences, questions and possibilities.":"Allyspan reúne apoyo comunitario, aprendizaje accesible y un diálogo público reflexivo. Damos espacio a las experiencias, las preguntas y las posibilidades de cada persona.","Community Awareness":"Concienciación comunitaria","Publications":"Publicaciones","Featured discussion paper":"Documento de debate destacado","14 November 2026":"14 de noviembre de 2026","Psychedelics in New York City":"Psicodélicos en la ciudad de Nueva York","Columbia’s research, unanswered questions, and who the evidence leaves out.":"La investigación de Columbia, las preguntas sin respuesta y las personas que quedan fuera de la evidencia.","Our first community awareness publication examines psychedelic research, psychiatric disability, access and commercialisation. It asks what trial findings can tell us - and what remains uncertain for people outside the populations studied.":"Nuestra primera publicación de concienciación comunitaria examina la investigación sobre psicodélicos, la discapacidad psiquiátrica, el acceso y la comercialización. Pregunta qué pueden decirnos los ensayos y qué sigue siendo incierto para quienes no forman parte de las poblaciones estudiadas.","Read the publication":"Leer la publicación","Learning across languages":"Aprender entre idiomas","Classroom Studio helps teachers create presentations that welcome multilingual learners.":"Classroom Studio ayuda a los docentes a crear presentaciones que acogen a estudiantes de distintos idiomas.","Discover Classroom Studio":"Descubre Classroom Studio","Support rooted in dignity":"Apoyo basado en la dignidad","Our mission centres belonging, anti-oppression and support that respects each person’s choices.":"Nuestra misión se centra en la pertenencia, la lucha contra la opresión y un apoyo que respeta las decisiones de cada persona.","Get to know Allyspan":"Conoce Allyspan","Share a resource simply":"Comparte un recurso fácilmente","Create a printable QR code for a lesson, workshop or community link. Free to use with no sign-up or scan tracking.":"Crea un código QR imprimible para una clase, un taller o un enlace comunitario. Gratis, sin registro ni seguimiento de escaneos.","Try the free QR code generator":"Prueba el generador de QR gratis","Work alongside Allyspan":"Colabora con Allyspan","See what is available now, what we are developing and how to start a conversation about partnership.":"Descubre qué está disponible, qué estamos desarrollando y cómo iniciar una conversación sobre colaboración.","Explore programs and partnerships":"Explora programas y colaboraciones","Support that stays beside you":"Apoyo que permanece a tu lado","Allyspan & Logo | Our Name and Meaning":"Allyspan y su logotipo | Nuestro nombre y significado","A name built around connection.":"Un nombre que nace de la conexión.","A symbol of support, growth, and possibility.":"Un símbolo de apoyo, crecimiento y posibilidades.","Our name":"Nuestro nombre","An ally. A bridge.":"Un aliado. Un puente.","A next step together.":"Un siguiente paso juntos.","Finding support can mean facing unfamiliar systems, complicated forms, or uncertainty about where to begin. Allyspan brings together two ideas that guide the organization we are building.":"Buscar apoyo puede implicar sistemas desconocidos, formularios complicados o dudas sobre por dónde empezar. Allyspan une dos ideas que guían la organización que estamos construyendo.","Ally":"Ally","means someone who stands beside you - listening, offering support, and respecting your choices.":"significa alguien que está a tu lado: escucha, ofrece apoyo y respeta tus decisiones.","Span":"Span","is the reach of a bridge: a connection between two points. For us, it represents the distance between a person and support that can feel out of reach.":"es el alcance de un puente: una conexión entre dos puntos. Para nosotros, representa la distancia entre una persona y un apoyo que puede parecer inaccesible.","Together,":"Juntos,","expresses our commitment to help bridge that distance through practical guidance, connections to appropriate services, and follow-through.":"expresa nuestro compromiso de ayudar a salvar esa distancia mediante orientación práctica, conexiones con servicios adecuados y seguimiento.","Our tree-and-sun emblem":"Nuestro emblema del árbol y el sol","Our symbol":"Nuestro símbolo","Many paths.":"Muchos caminos.","Connected sources of strength.":"Fuentes de fortaleza conectadas.","The tree represents life, resilience, and growth supported by connection. Its intertwined trunk reflects the relationships between individuals, families, communities, and professionals.":"El árbol representa la vida, la resiliencia y el crecimiento sostenido por la conexión. Su tronco entrelazado refleja las relaciones entre personas, familias, comunidades y profesionales.","Each branch and leaf suggests a different path, need, or possibility. All belong to one tree - a reminder to see the whole person, beyond a single challenge.":"Cada rama y hoja sugiere un camino, una necesidad o una posibilidad diferente. Todas pertenecen al mismo árbol: un recordatorio de ver a la persona en su totalidad, más allá de un solo desafío.","The sun":"El sol","Hope, clarity, and the possibility of seeing a next step.":"Esperanza, claridad y la posibilidad de ver un siguiente paso.","The stepped foundation":"La base escalonada","Stability and gradual progress. A small first step can open a way forward.":"Estabilidad y progreso gradual. Un pequeño primer paso puede abrir un camino.","The gold":"El dorado","Warmth and the value of every person.":"Calidez y el valor de cada persona.","Our promise":"Nuestra promesa","Support That Stays Beside You.":"Apoyo que permanece a tu lado.","Our tagline expresses continuity, respect, and a commitment to work alongside each person. Your choices matter. Support should help you move toward your own goals, at your own pace.":"Nuestro lema expresa continuidad, respeto y el compromiso de trabajar junto a cada persona. Tus decisiones importan. El apoyo debe ayudarte a avanzar hacia tus propios objetivos, a tu propio ritmo.","Two versions. One identity.":"Dos versiones. Una identidad.","Our emblem appears in two forms: a tree and sun without a letter, and a version with an":"Nuestro emblema tiene dos versiones: un árbol y un sol sin letra, y otra con una","A":"A","inside the sun that connects it directly to the Allyspan name.":"dentro del sol, que lo vincula directamente con el nombre Allyspan.","Both carry the same meaning: connection, dignity, and room to grow. The feeling we want to communicate is simple:":"Ambas transmiten el mismo significado: conexión, dignidad y espacio para crecer. Queremos comunicar algo sencillo:","“I am respected here. Someone will help me find a way forward.”":"«Aquí me respetan. Alguien me ayudará a encontrar cómo seguir adelante».","Our Mission | Allyspan":"Nuestra misión | Allyspan","Connecting people with support.":"Conectamos a las personas con el apoyo.","Working toward a more equitable community.":"Trabajamos por una comunidad más equitativa.","Why we exist":"Por qué existimos","Dignity, access,":"Dignidad, acceso","and a way forward.":"y un camino a seguir.","Allyspan’s mission is to reduce barriers to community resources, challenge oppression and social exclusion, and support people in pursuing goals they define for themselves.":"La misión de Allyspan es reducir las barreras de acceso a los recursos comunitarios, cuestionar la opresión y la exclusión social, y apoyar a las personas en la búsqueda de los objetivos que ellas mismas definen.","We are building an organization that brings together practical guidance, connections to appropriate agencies, community education, and thoughtful follow-through. Every person deserves to be heard, treated with respect, and included in decisions that affect their life.":"Estamos construyendo una organización que reúne orientación práctica, conexiones con agencias adecuadas, educación comunitaria y seguimiento cuidadoso. Toda persona merece ser escuchada, tratada con respeto e incluida en las decisiones que afectan su vida.","What guides us":"Qué nos guía","Anti-oppression":"La lucha contra la opresión","in everyday practice.":"en la práctica cotidiana.","Anti-oppression means recognizing how racism, poverty, ableism, discrimination, and unequal power can shape someone’s access to support. We aim to challenge these barriers in the way we listen, design programs, and work with others.":"Luchar contra la opresión implica reconocer cómo el racismo, la pobreza, el capacitismo, la discriminación y las desigualdades de poder pueden afectar el acceso al apoyo. Buscamos cuestionar esas barreras en nuestra forma de escuchar, diseñar programas y colaborar.","Choice and dignity.":"Elección y dignidad.","We respect people’s identities, experiences, and right to make their own decisions.":"Respetamos las identidades, las experiencias y el derecho de cada persona a tomar sus propias decisiones.","Access and inclusion.":"Acceso e inclusión.","We seek to make information understandable and participation more accessible across languages, backgrounds, and abilities.":"Buscamos que la información sea comprensible y la participación más accesible entre idiomas, contextos y capacidades.","Accountability.":"Responsabilidad.","We welcome feedback, acknowledge limits, and use what we learn to improve our work.":"Agradecemos los comentarios, reconocemos nuestros límites y utilizamos lo aprendido para mejorar.","Our beginnings":"Nuestros comienzos","Experience that informs":"Experiencias que orientan","a shared mission.":"una misión compartida.","Allyspan’s direction is informed by its founder’s experiences and a commitment to building more respectful, accessible systems of support.":"La dirección de Allyspan se nutre de las experiencias de su fundador y del compromiso de construir sistemas de apoyo más respetuosos y accesibles.","These experiences inform a central concern: how institutions respond to people, and what happens when someone faces barriers to help. Allyspan carries that concern into an organizational commitment to practical support, human dignity, and community connection.":"Esas experiencias plantean una preocupación central: cómo responden las instituciones a las personas y qué ocurre cuando alguien encuentra barreras para recibir ayuda. Allyspan convierte esa preocupación en un compromiso organizacional con el apoyo práctico, la dignidad humana y la conexión comunitaria.","As we grow, the perspectives of people using our programs, community partners, staff, and volunteers will help shape our work.":"A medida que crezcamos, las perspectivas de quienes usan nuestros programas, de nuestros socios comunitarios, del personal y del voluntariado ayudarán a dar forma a nuestro trabajo.","Our direction":"Nuestro rumbo","Support that stays beside you.":"Apoyo que permanece a tu lado.","We are developing our programs step by step, with care for the people they are intended to serve. Our mission is a commitment that guides this work as Allyspan takes shape.":"Desarrollamos nuestros programas paso a paso, pensando en las personas a quienes servirán. Nuestra misión es el compromiso que guía este trabajo mientras Allyspan toma forma.","Programs and Partnerships | Allyspan":"Programas y colaboraciones | Allyspan","A place to explore options.":"Un espacio para explorar opciones.","A connection to your next step.":"Una conexión con tu siguiente paso.","Our approach":"Nuestro enfoque","Listen. Connect.":"Escuchar. Conectar.","Follow through.":"Dar seguimiento.","Support begins with understanding what matters to you. Our planned Community Navigation program will help people explore available resources, connect with appropriate agencies, and work through obstacles to accessing support.":"El apoyo comienza por comprender lo que te importa. Nuestro programa previsto de Orientación Comunitaria ayudará a explorar recursos disponibles, conectar con agencias adecuadas y superar obstáculos para acceder al apoyo.","Listen:":"Escuchar:","understand your priorities without assuming what you need.":"comprender tus prioridades sin dar por hecho lo que necesitas.","Explore:":"Explorar:","explain relevant options and help you identify questions to ask.":"explicar opciones pertinentes y ayudarte a identificar preguntas.","Connect:":"Conectar:","assist with referrals to organizations suited to your needs.":"ayudar con derivaciones a organizaciones adecuadas para tus necesidades.","Follow through:":"Dar seguimiento:","check whether a connection was useful and explore next steps together.":"comprobar si la conexión fue útil y explorar juntos los siguientes pasos.","In development":"En desarrollo","Community Navigation":"Orientación Comunitaria","We are building a program focused on nonclinical resource navigation, assisted referrals, and follow-up. Areas may include basic needs, benefits, employment resources, housing resources, and community services, depending on program capacity and available partnerships.":"Estamos creando un programa centrado en la orientación no clínica sobre recursos, las derivaciones asistidas y el seguimiento. Podrá abarcar necesidades básicas, prestaciones, recursos de empleo, vivienda y servicios comunitarios, según la capacidad del programa y las colaboraciones disponibles.","This program is in development. Intake and ongoing navigation services are not yet open. We will share eligibility, availability, and how to request support when the program is ready.":"Este programa está en desarrollo. Todavía no se aceptan solicitudes ni se ofrecen servicios continuos de orientación. Cuando esté listo, publicaremos los requisitos, la disponibilidad y cómo solicitar apoyo.","Available now":"Disponible ahora","Classroom Studio is live and available with sign-in. Allyspan’s presentation tool helps educators prepare and share presentations with translation options so more learners in multilingual classrooms can follow along.":"Classroom Studio está disponible al iniciar sesión. Esta herramienta de Allyspan ayuda a los docentes a preparar y compartir presentaciones con opciones de traducción para que más estudiantes puedan seguir las clases multilingües.","Looking ahead":"Mirando al futuro","Learning and":"Aprendizaje y","community participation.":"participación comunitaria.","We plan to develop nonformal community workshops, opportunities for student and community contributions, and ways for volunteers and interns to participate. These initiatives will be introduced as their staffing, partnerships, and structure are established.":"Planeamos desarrollar talleres comunitarios no formales, oportunidades de contribución para estudiantes y la comunidad, y formas de participar como voluntario o pasante. Estas iniciativas se presentarán cuando se establezcan el personal, las colaboraciones y su estructura.","Our approach is grounded in anti-oppression, respect for individual choices, and attention to the barriers people face. We aim to work alongside communities and learn from their experiences.":"Nuestro enfoque se basa en la lucha contra la opresión, el respeto a las decisiones individuales y la atención a las barreras que enfrentan las personas. Queremos trabajar junto a las comunidades y aprender de sus experiencias.","Get in touch":"Contáctanos","Start with a conversation.":"Comencemos con una conversación.","For general questions or partnership inquiries,":"Para consultas generales o sobre colaboraciones,","connect with Allyspan":"contacta con Allyspan",".":".","For partners and funders":"Para socios y financiadores","Build useful support.":"Construyamos un apoyo útil.","Start with clear expectations.":"Empecemos con expectativas claras.","Our work connects accessible learning, community resources and public discussion. Classroom Studio and QR Studio are available now. Community Navigation and additional workshops are in development; we will publish service availability and eligibility before opening intake.":"Nuestro trabajo conecta aprendizaje accesible, recursos comunitarios y diálogo público. Classroom Studio y QR Studio ya están disponibles. Orientación Comunitaria y otros talleres están en desarrollo; publicaremos la disponibilidad y los requisitos antes de abrir solicitudes.","We welcome conversations with educators, community organizations and prospective funders about program priorities, resources, accessibility and how outcomes would be assessed. We distinguish current activity from planned work and will describe the scope and responsibilities of any partnership before it begins.":"Agradecemos el diálogo con docentes, organizaciones comunitarias y posibles financiadores sobre prioridades, recursos, accesibilidad y evaluación de resultados. Distinguimos lo que hacemos hoy de lo previsto y definiremos el alcance y las responsabilidades de cada colaboración antes de comenzar.","Connect | Allyspan":"Contacto | Allyspan","Every connection begins with a hello.":"Cada conexión comienza con un saludo.","We’re glad you’re here.":"Nos alegra que estés aquí.","Let’s start":"Empecemos","a conversation.":"una conversación.","Have a question, an idea for your community, or a possibility for working together? We welcome thoughtful conversations and the perspectives you bring.":"¿Tienes una pregunta, una idea para tu comunidad o una propuesta para colaborar? Valoramos las conversaciones reflexivas y las perspectivas que aportas.","For general questions, partnerships and community connections:":"Para consultas generales, colaboraciones y conexiones comunitarias:","hello@allyspan.org":"hello@allyspan.org","A little support":"Un poco de apoyo","for your next lesson.":"para tu próxima clase.","Whether you’re creating your first presentation, exploring multilingual learning, or sharing feedback, we’d love to hear how Classroom Studio can work better for you.":"Tanto si creas tu primera presentación, exploras el aprendizaje multilingüe o compartes comentarios, queremos saber cómo Classroom Studio puede servirte mejor.","For Studio questions, technical issues and suggestions:":"Para preguntas sobre Studio, problemas técnicos y sugerencias:","allyspanstudio@allyspan.org":"allyspanstudio@allyspan.org","If something isn’t working, include a short description and the device or browser you’re using. Please leave out student names, passwords and other private information.":"Si algo falla, incluye una breve descripción y el dispositivo o navegador que usas. No incluyas nombres de estudiantes, contraseñas ni otros datos privados.","Classroom Studio Guide for Teachers and Learners | Allyspan":"Guía de Classroom Studio para docentes y estudiantes | Allyspan","One lesson. More ways to participate.":"Una lección. Más formas de participar.","A basic guide for multilingual classrooms.":"Una guía básica para aulas multilingües.","Meet the Studio":"Conoce Studio","Create once.":"Crea una vez.","Connect across languages.":"Conecta entre idiomas.","Classroom Studio is Allyspan’s online presentation workspace for educators. Create visual lessons, add multilingual text, and share a lesson through a QR code or link so students can follow along in an available language they understand.":"Classroom Studio es el espacio de presentaciones en línea de Allyspan para docentes. Crea lecciones visuales, añade texto multilingüe y comparte mediante un QR o enlace para que los estudiantes sigan la clase en un idioma disponible que comprendan.","Teachers sign in with Google to create and save presentations. Students can open shared lessons without an account, choose a lesson language, and move through the slides at their own pace.":"Los docentes inician sesión con Google para crear y guardar presentaciones. Los estudiantes pueden abrir clases compartidas sin cuenta, elegir el idioma y avanzar a su propio ritmo.","For teachers":"Para docentes","Create your":"Crea tu","first lesson.":"primera lección.","Sign in.":"Inicia sesión.","Open Classroom Studio and sign in with Google. Find saved lessons under My presentations.":"Abre Classroom Studio e inicia sesión con Google. Encontrarás tus clases guardadas en My presentations (Mis presentaciones).","Choose a starting point.":"Elige un punto de partida.","Browse templates or create a blank presentation. Give your lesson a name you will recognize later.":"Explora las plantillas o crea una presentación en blanco. Ponle un nombre que puedas reconocer más adelante.","Build your slides.":"Prepara tus diapositivas.","Edit the English text, add images, and move objects into place. Keep each slide focused and leave room for translations.":"Edita el texto en inglés, añade imágenes y coloca los objetos. Mantén cada diapositiva centrada en una idea y deja espacio para las traducciones.","Choose languages.":"Elige los idiomas.","Open Languages in the editor and select those your class needs. Translate your text and review the wording for accuracy and classroom meaning.":"Abre Languages (Idiomas) en el editor y selecciona los que necesita tu clase. Traduce el texto y revisa su precisión y sentido en el aula.","Save and preview.":"Guarda y previsualiza.","Confirm the save status says Saved before closing. Select Present to check the lesson before class.":"Antes de cerrar, confirma que el estado diga Saved (Guardado). Selecciona Present (Presentar) para revisar la clase antes de enseñarla.","Share and present":"Compartir y presentar","Invite your":"Invita a tus","students in.":"estudiantes a participar.","Keep":"Mantén","Include QR slide 0":"Include QR slide 0 (Incluir diapositiva QR 0)","enabled for a welcome screen. Selecting":"activado para mostrar la bienvenida. Al seleccionar","Present":"Present (Presentar)","turns sharing on and displays the lesson QR code and link. You can also open":"se activa la opción de compartir y se muestran el QR y el enlace de la clase. También puedes abrir","Share & QR":"Share & QR (Compartir y QR)","in the editor.":"en el editor.","Use":"Usa","QR options":"QR options (Opciones QR)","to copy the complete lesson link, choose a QR color, or download the QR image. Test the QR code on a second device before class.":"para copiar el enlace completo, elegir el color del QR o descargar su imagen. Prueba el QR en otro dispositivo antes de la clase.","The same link continues to work as you update a lesson. Anyone with the link can view it while sharing is on. Use":"El mismo enlace sigue funcionando cuando actualizas una clase. Cualquier persona con el enlace puede verla mientras esté activada la opción de compartir. Usa","Turn sharing off":"Turn sharing off (Desactivar compartir)","in the sharing window when you want to stop access.":"en la ventana de compartir cuando quieras detener el acceso.","For learners":"Para estudiantes","Scan. Choose.":"Escanea. Elige.","Follow along.":"Sigue la clase.","Scan the teacher’s QR code or open the complete shared lesson link. No student sign-in is needed.":"Escanea el QR del docente o abre el enlace completo de la clase. No necesitas iniciar sesión como estudiante.","Choose an available":"Elige un idioma disponible en","Lesson language":"Lesson language (Idioma de la clase)",", then use":"y usa","Next":"Next (Siguiente)","and":"y","Back":"Back (Atrás)","to explore the slides. When available, show English alongside the translation. An internet connection is needed to open a shared lesson.":"para recorrer las diapositivas. Cuando sea posible, muestra el inglés junto a la traducción. Necesitas internet para abrir una clase compartida.","Before class":"Antes de clase","A few useful habits.":"Algunos hábitos útiles.","Check translations.":"Revisa las traducciones.","Review important wording before teaching, particularly instructions and unfamiliar terms.":"Revisa las expresiones importantes antes de enseñar, especialmente las instrucciones y los términos poco conocidos.","Keep sharing intentional.":"Comparte con intención.","Share only material appropriate for everyone who may receive the link. Presenter notes stay in the editor and are not included in the shared student lesson.":"Comparte solo contenido adecuado para todas las personas que puedan recibir el enlace. Las notas del presentador permanecen en el editor y no se incluyen en la clase compartida con estudiantes.","Prepare an offline copy.":"Prepara una copia sin conexión.","Download the presentation with its saved translations and included media. Extract the ZIP, then open":"Descarga la presentación con sus traducciones guardadas y los archivos multimedia incluidos. Extrae el ZIP y abre","index.html":"index.html","in a modern browser. A Home Screen shortcut still needs internet.":"en un navegador moderno. Un acceso directo en la pantalla de inicio sigue necesitando internet.","Test your display.":"Prueba la pantalla.","Use Full screen for the teacher screen. Phone browser controls and fullscreen behavior vary by device.":"Usa Full screen (Pantalla completa) en la pantalla del docente. Los controles del navegador del teléfono y el funcionamiento de pantalla completa varían según el dispositivo.","Help and feedback":"Ayuda y comentarios","A platform":"Una plataforma","we are improving together.":"que mejoramos juntos.","Classroom Studio continues to develop, so features and controls may change. To report an issue, sign in, return to the home workspace, and select":"Classroom Studio sigue en desarrollo; sus funciones y controles pueden cambiar. Para informar de un problema, inicia sesión, vuelve al espacio principal y selecciona","Report a problem":"Report a problem (Informar de un problema)","in the sidebar.":"en la barra lateral.","Explain what you were trying to do, what happened, and which device and browser you used. Include any error message, but leave out student names and private information.":"Explica qué intentabas hacer, qué ocurrió y qué dispositivo y navegador usaste. Incluye los mensajes de error, pero no nombres de estudiantes ni información privada.","Ready to begin?":"¿Listo para empezar?","Your next lesson starts here.":"Tu próxima clase comienza aquí.","Open Classroom Studio":"Abrir Classroom Studio","Free QR Code Generator | Allyspan":"Generador de códigos QR gratis | Allyspan","A little link, made shareable":"Un pequeño enlace, listo para compartir","QR":"QR","code":"código","A free QR code generator for teachers and everyday sharing. No sign-up. No tracking.":"Un generador de QR gratis para docentes y para compartir cada día. Sin registro. Sin seguimiento.","Add your link":"Añade tu enlace","Website URL":"URL del sitio web","Paste or type a link":"Pega o escribe un enlace","Your QR code opens this exact page when someone scans it.":"Al escanear tu QR, se abre exactamente esta página.","Generate":"Generar","Your link stays in your browser. It isn’t saved or sent to Allyspan.":"Tu enlace permanece en tu navegador. No se guarda ni se envía a Allyspan.","Your QR code":"Tu código QR","Allyspan edition":"Edición Allyspan","Your code will appear here":"Tu código aparecerá aquí","after you add a link":"después de añadir un enlace","Download":"Descargar","A free QR code generator with no sign-up":"Un generador de QR gratis y sin registro","Create a static QR code for a website link, then download it as a 1184 × 1294-pixel PNG image. Use it on classroom slides, workshop handouts, event posters or everyday resources. The tool works in your browser without an account or a payment step.":"Crea un QR estático para un enlace web y descárgalo como imagen PNG de 1184 × 1294 píxeles. Úsalo en diapositivas, materiales de talleres, carteles o recursos cotidianos. Funciona en tu navegador, sin cuenta ni pago.","How it works":"Cómo funciona","Paste a complete website address. Check that it is the page you want people to open.":"Pega una dirección web completa. Comprueba que sea la página que quieres que se abra.","Generate your code":"Genera tu código","Select Generate to create the QR code locally in your browser. Your link is not sent to Allyspan.":"Selecciona Generar para crear el QR localmente en tu navegador. Tu enlace no se envía a Allyspan.","Download and test":"Descarga y prueba","Download the PNG, add it to your material and scan a test copy before sharing or printing.":"Descarga el PNG, añádelo a tu material y escanea una copia de prueba antes de compartirlo o imprimirlo.","A QR code generator with no tracking":"Un generador de QR sin seguimiento","Your code contains the destination link itself. It does not pass through an Allyspan redirect, scan counter or subscription service. Entered links and generated images are not uploaded to or saved by Allyspan. This tool page has no analytics or advertising trackers.":"El código contiene el enlace de destino. No pasa por redirecciones de Allyspan, contadores de escaneos ni servicios de suscripción. Allyspan no recibe ni guarda los enlaces introducidos ni las imágenes generadas. Esta página no tiene herramientas de analítica ni rastreadores publicitarios.","Your browser holds the link while the page is open; a downloaded image stays wherever you save it. Visiting this page still involves ordinary web-hosting requests. A website opened after scanning may use its own analytics or tracking.":"El navegador conserva el enlace mientras la página está abierta; la imagen descargada queda donde la guardes. Visitar esta página sigue implicando solicitudes normales de alojamiento web. El sitio que se abra al escanear puede tener sus propias herramientas de analítica o seguimiento.","QR codes for teachers and community workshops":"Códigos QR para docentes y talleres comunitarios","Help learners open a shared lesson, an accessible resource or a feedback page without typing a long address. Pair the QR code with a short written link and a clear description so people can choose how to access the information. Always test access permissions from a student’s device.":"Ayuda a abrir una clase compartida, un recurso accesible o una página de comentarios sin escribir una dirección larga. Acompaña el QR de un enlace escrito breve y una descripción clara para que cada persona elija cómo acceder. Prueba siempre los permisos desde un dispositivo de estudiante.","For multilingual slide presentations with student sharing, explore":"Para presentaciones multilingües que puedes compartir con estudiantes, conoce",". For a single link to print or share, this QR tool is ready to use without sign-in.":". Para imprimir o compartir un solo enlace, esta herramienta QR está lista sin iniciar sesión.","Frequently asked questions":"Preguntas frecuentes","Is it free?":"¿Es gratis?","Yes. Generating and downloading your QR code is free. There is no paid plan required to keep a generated code working.":"Sí. Generar y descargar el QR es gratis. No necesitas un plan de pago para que el código siga funcionando.","Do I need an account?":"¿Necesito una cuenta?","No. Allyspan QR Studio does not require an account, email address or sign-up.":"No. Allyspan QR Studio no requiere cuenta, correo electrónico ni registro.","Is my link stored?":"¿Se guarda mi enlace?","Not by Allyspan. Your link is processed in the browser and is not uploaded to our servers. A downloaded QR image contains the link you entered, so share that image only with the audience you intend.":"Allyspan no lo guarda. El enlace se procesa en el navegador y no se sube a nuestros servidores. La imagen descargada contiene ese enlace: compártela solo con el público previsto.","Does the code expire?":"¿El código caduca?","The static QR code has no built-in expiry or Allyspan subscription dependency. It keeps pointing to the encoded address. That destination still needs to remain available, and a time-limited destination link can expire.":"El QR estático no tiene caducidad integrada ni depende de una suscripción a Allyspan. Sigue apuntando a la dirección codificada. El destino debe continuar disponible; un enlace de destino temporal sí puede caducar.","Can I print it?":"¿Puedo imprimirlo?","Yes. Use the downloaded PNG, keep the white space around the code, and avoid stretching or cropping it. Print a test at the intended size and scan it with a phone before producing more copies. Include a written link as an alternative.":"Sí. Usa el PNG descargado, conserva el espacio blanco alrededor del código y evita estirarlo o recortarlo. Imprime una prueba al tamaño previsto y escanéala antes de producir más copias. Incluye un enlace escrito como alternativa.","The Allyspan Journal | Community Awareness Publications":"The Allyspan Journal | Publicaciones de concienciación comunitaria","The Allyspan Journal":"The Allyspan Journal","Lived experience held to the evidence":"La experiencia vivida a la luz de la evidencia","The Allyspan Journal publishes research and policy alongside lived experience and perspectives from people of all backgrounds.":"The Allyspan Journal publica investigación y políticas junto con experiencias vividas y perspectivas de personas de todos los contextos.","Community awareness":"Concienciación comunitaria","Read the article":"Leer el artículo","Submission Privacy | The Allyspan Journal":"Privacidad de los envíos | The Allyspan Journal","Submission privacy":"Privacidad de los envíos","Your work is not published automatically":"Tu trabajo no se publica automáticamente","A submission is for confidential editorial assessment. Publication requires a separate agreement and your approval of the final proof.":"El envío es para una evaluación editorial confidencial. La publicación requiere un acuerdo aparte y tu aprobación de la prueba final.","What happens when you send":"Qué ocurre al enviar","The live form sends your manuscript, selected attachments, author details and declarations over HTTPS through Cloudflare to Resend for delivery to the Journal's private editorial inbox. The address journal@allyspan.org forwards to the owner's verified Gmail inbox. Authorized editorial personnel and necessary service providers may process submissions for editorial assessment.":"El formulario envía tu manuscrito, los archivos seleccionados, los datos de autoría y las declaraciones por HTTPS, a través de Cloudflare y Resend, a la bandeja editorial privada de la revista. journal@allyspan.org reenvía los mensajes a la cuenta Gmail verificada del propietario. El personal editorial autorizado y los proveedores necesarios pueden procesar los envíos para su evaluación editorial.","The submission service does not create public manuscript links or save files in GitHub, a public bucket or a submission database. Files pass through the service into email. A separate receipt is requested for the corresponding author.":"El servicio no crea enlaces públicos a manuscritos ni guarda archivos en GitHub, contenedores públicos o bases de datos de envíos. Los archivos pasan por el servicio hasta el correo electrónico. Se solicita un acuse de recibo independiente para el autor de correspondencia.","Unfinished entries and technical information":"Entradas sin terminar e información técnica","Unfinished entries remain in the open page; the form does not save them in browser storage. When sending is enabled, Cloudflare Turnstile checks requests and the service applies a short-term rate limit using the request IP.":"Las entradas sin terminar permanecen en la página abierta; el formulario no las guarda en el almacenamiento del navegador. Cuando se habilita el envío, Cloudflare Turnstile comprueba las solicitudes y el servicio aplica un límite temporal de solicitudes mediante la IP.","The submission code does not log form contents or include them in analytics. Website and email providers may process ordinary connection, usage and delivery information according to their service settings.":"El código del formulario no registra su contenido ni lo incluye en analítica. Los proveedores web y de correo pueden procesar información habitual de conexión, uso y entrega según la configuración de sus servicios.","Retention, withdrawal and deletion":"Conservación, retirada y eliminación","Submission emails, attachments and editorial correspondence remain in the private editorial mailbox until deleted. This version has no automatic expiry process. Contact journal@allyspan.org with your submission reference to request withdrawal or deletion. Service providers may retain technical records according to their settings.":"Los correos de envío, los adjuntos y la correspondencia editorial permanecen en la bandeja privada hasta que se eliminen. Esta versión no tiene caducidad automática. Contacta con journal@allyspan.org e indica tu referencia para solicitar retirada o eliminación. Los proveedores pueden conservar registros técnicos según sus ajustes.","Do not include confidential participant records, signed consent forms, home addresses, student IDs or unnecessary personal information. Explain pseudonym or safety requests before publication.":"No incluyas registros confidenciales de participantes, consentimientos firmados, domicilios, identificaciones estudiantiles ni datos personales innecesarios. Explica las solicitudes de seudónimo o seguridad antes de publicar.","Return to the submission page":"Volver a la página de envío","Submit Your Work | The Allyspan Journal":"Envía tu trabajo | The Allyspan Journal","Read the Journal":"Leer la revista","Private submissions for editorial review":"Envíos privados para revisión editorial","Complete the form and review your details before sending. Nothing is published automatically. Sending becomes available after the security check.":"Completa el formulario y revisa los datos antes de enviarlos. Nada se publica automáticamente. El envío se habilita después de la comprobación de seguridad.","What happens after you submit":"Qué ocurre después de enviar","An editor reads your complete submission. We aim to give an initial response within 15 business days.":"Un editor lee tu envío completo. Procuramos dar una primera respuesta en un plazo de 15 días hábiles.","If it is a fit, we work with you on revisions.":"Si encaja, trabajamos contigo en las revisiones.","Research articles receive independent methodological review by two independent reviewers. Reviewers are confidential to authors; publication waits if suitable reviewers are unavailable.":"Los artículos de investigación reciben una revisión metodológica independiente por dos revisores independientes. Sus identidades no se revelan a los autores; si no hay revisores adecuados, la publicación espera.","We publish with the article type and actual review status stated, after your final proof approval.":"Publicamos indicando el tipo de artículo y su estado real de revisión, después de tu aprobación de la prueba final.","Explore the editorial review process":"Conoce el proceso de revisión editorial","Submit Your Work":"Envía tu trabajo","Prepare your submission":"Prepara tu envío","Required fields are marked *.":"Los campos obligatorios se marcan con *.","1. Your work":"1. Tu trabajo","2. About the authors":"2. Sobre la autoría","3. Review and declarations":"3. Revisión y declaraciones","Your submission stays private.":"Tu envío permanece privado.","Nothing is published automatically. Editorial review, final article design and author proof approval come before publication.":"Nada se publica automáticamente. La revisión editorial, el diseño final y tu aprobación de la prueba preceden a la publicación.","Submit initially in English. If English isn't your first language, tell us when you submit - we'll discuss translation, and we publish in your language too where we can.":"Envía inicialmente en inglés. Si el inglés no es tu primer idioma, indícalo al enviar: hablaremos de la traducción y, cuando podamos, publicaremos también en tu idioma.","Your work":"Tu trabajo","Article title":"Título del artículo","*":"*","Article type *":"Tipo de artículo *","Choose one":"Elige una opción","Research Article":"Artículo de investigación","Literature or Evidence Review":"Revisión bibliográfica o de evidencia","Policy Review or Policy Analysis":"Revisión o análisis de políticas","Practice and Community Analysis":"Análisis de práctica y comunidad","Student Perspectives / Community Voices":"Perspectivas estudiantiles / Voces comunitarias","Book or Resource Review":"Reseña de libro o recurso","Commentary":"Comentario","Letter responding to published work":"Carta sobre un trabajo publicado","Main topic *":"Tema principal *","Community life":"Vida comunitaria","Systems and services":"Sistemas y servicios","Justice and rights":"Justicia y derechos","Manuscript word count":"Número de palabras del manuscrito","Choose an article type to see its word range.":"Elige un tipo de artículo para ver su extensión.","Plain-language summary":"Resumen en lenguaje claro","100-150 words.":"100-150 palabras.","0 words":"0 palabras","Keywords":"Palabras clave","4-6 different keywords or phrases, separated by commas.":"Entre 4 y 6 palabras o frases clave diferentes, separadas por comas.","Editable manuscript":"Manuscrito editable","DOCX, DOC, Pages, TXT, RTF or ODT. A PDF may accompany your editable manuscript. Total attachments: up to 10 MB.":"DOCX, DOC, Pages, TXT, RTF u ODT. Puede acompañarse de un PDF. Total de adjuntos: hasta 10 MB.","Companion PDF (optional)":"PDF complementario (opcional)","A PDF does not replace the editable manuscript.":"Un PDF no sustituye al manuscrito editable.","Supporting images (optional)":"Imágenes de apoyo (opcional)","PNG or JPG. Add a caption, alt text and source or permission details for each image.":"PNG o JPG. Añade pie de imagen, texto alternativo y datos de fuente o permisos para cada una.","Manuscript language *":"Idioma del manuscrito *","Other":"Otro","Language and translation notes (optional)":"Idioma y notas de traducción (opcional)","Continue to authors":"Continuar a la autoría","About the authors":"Sobre la autoría","No university affiliation is required. People of all backgrounds may contribute.":"No se requiere afiliación universitaria. Pueden contribuir personas de todos los contextos.","Your publication name":"Tu nombre para publicación","Corresponding author email":"Correo del autor de correspondencia","Private - used for editorial correspondence, not displayed with the article.":"Privado: se usa para correspondencia editorial y no se muestra en el artículo.","Role or affiliation (optional)":"Cargo o afiliación (opcional)","ORCID (optional)":"ORCID (opcional)","If you have one, enter your ORCID iD or profile URL.":"Si tienes ORCID, introduce tu identificador o el enlace a tu perfil.","Short biography":"Biografía breve","50-80 words.":"50-80 palabras.","Your contribution":"Tu contribución","Describe your role in creating this work.":"Describe tu papel en la creación del trabajo.","Add a coauthor":"Añadir coautor","Pseudonym or safety request (optional)":"Solicitud de seudónimo o seguridad (opcional)","Editors must privately verify the author and agree on accountability and safety arrangements. Do not include home addresses, student IDs or unnecessary personal data.":"Los editores deben verificar la identidad del autor de forma privada y acordar medidas de responsabilidad y seguridad. No incluyas domicilios, identificaciones estudiantiles ni datos personales innecesarios.","Continue to review":"Continuar a la revisión","Review and declarations":"Revisión y declaraciones","Edit your work":"Editar el trabajo","Edit author details":"Editar datos de autoría","Funding and conflicts of interest":"Financiación y conflictos de interés","State any funding and relevant interests, or write None.":"Indica la financiación y los intereses pertinentes, o escribe None (Ninguno).","AI use and prior dissemination":"Uso de IA y difusión previa","Describe any AI assistance, prior versions or related work, or write None.":"Describe la asistencia de IA, las versiones previas o los trabajos relacionados, o escribe None (Ninguno).","Does this work involve research with human participants? *":"¿El trabajo incluye investigación con participantes humanos? *","No":"No","Yes":"Sí","Ethics and consent details (optional)":"Detalles de ética y consentimiento (opcional)","State the reviewing body, determination, reference if available, and consent approach. Do not upload confidential consent forms or identifying participant records.":"Indica el órgano revisor, la decisión, la referencia si existe y el procedimiento de consentimiento. No subas consentimientos confidenciales ni registros que identifiquen a participantes.","Visual permissions":"Permisos de materiales visuales","If visuals are included, confirm ownership, source and permission to publish. Otherwise write Not applicable.":"Si incluyes imágenes, confirma propiedad, fuente y permiso de publicación. En caso contrario, escribe Not applicable (No corresponde).","Author declarations *":"Declaraciones de autoría *","All authors approve this submission and the information is accurate.":"Todos los autores aprueban este envío y la información es correcta.","Required permissions, ethics information and disclosures are complete.":"Los permisos, la información ética y las declaraciones requeridas están completos.","I have read the contributor guide and the submission privacy notice.":"He leído la guía para colaboradores y el aviso de privacidad de los envíos.","I understand this sends work for review and does not publish it. Publication rights are agreed separately after acceptance.":"Entiendo que esto envía el trabajo a revisión y no lo publica. Los derechos de publicación se acuerdan por separado tras la aceptación.","Leave this field empty":"Deja este campo vacío","Your manuscript will be sent privately to the Journal. A receipt will be requested for your email address.":"Tu manuscrito se enviará de forma privada a la revista. Se solicitará un acuse de recibo a tu correo.","Preview submission":"Previsualizar el envío","Send for editorial review":"Enviar a revisión editorial","For Journal questions: journal@allyspan.org. Sending becomes available after the security check.":"Consultas sobre la revista: journal@allyspan.org. El envío se habilita después de la comprobación de seguridad.","Your submission preview":"Vista previa de tu envío","Not submitted. Nothing has been sent or saved.":"No se ha enviado. No se ha enviado ni guardado nada.","Return to form":"Volver al formulario","How to Publish Your Work | The Allyspan Journal":"Cómo publicar tu trabajo | The Allyspan Journal","Explore the article:":"Explora el artículo:","Explore the guide":"Explora la guía","Welcome & scope":"Bienvenida y alcance","Choose your format":"Elige tu formato","Writing & visuals":"Redacción y materiales visuales","Ethics & responsibility":"Ética y responsabilidad","Editorial review":"Revisión editorial","Rights & corrections":"Derechos y correcciones","Community discussion":"Diálogo comunitario","Checklist & resources":"Lista de verificación y recursos","Contributor guide":"Guía para colaboradores","Welcome to The Allyspan Journal":"Bienvenido a The Allyspan Journal","Purpose, scope and editorial identity":"Propósito, alcance e identidad editorial","Students, researchers, practitioners and community contributors are welcome. You do not need a university affiliation to contribute.":"Damos la bienvenida a estudiantes, investigadores, profesionales y colaboradores comunitarios. No necesitas afiliación universitaria para contribuir.","Research, policy, student perspectives and community voices":"Investigación, políticas, perspectivas estudiantiles y voces comunitarias","A publication of Allyspan connecting academic inquiry with the realities of people navigating care, public services and legal systems. We welcome thoughtful work that improves understanding, examines inequity and offers practical, evidence-informed possibilities.":"Una publicación de Allyspan que conecta la investigación académica con las realidades de quienes buscan atención y navegan por los servicios públicos y los sistemas legales. Acogemos trabajos reflexivos que mejoren la comprensión, examinen la inequidad y propongan posibilidades prácticas basadas en la evidencia.","Who may contribute":"Quién puede contribuir","Students, researchers, practitioners, advocates and community contributors may submit. An advanced degree, university affiliation or personal connection to Allyspan is not required. Publication depends on quality, relevance, ethics and editorial capacity. Lived experience is valuable knowledge; broad factual or causal claims still need appropriate evidence.":"Pueden enviar estudiantes, investigadores, profesionales, defensores y colaboradores comunitarios. No se exige posgrado, afiliación universitaria ni vínculo personal con Allyspan. La publicación depende de calidad, pertinencia, ética y capacidad editorial. La experiencia vivida aporta conocimiento valioso; las afirmaciones generales de hecho o causalidad siguen necesitando evidencia adecuada.","Submit initially in English. If English isn't your first language, tell us when you submit - we'll discuss translation, and we publish in your language too where we can. Review takes place in English; publication in another language depends on translation and review capacity.":"Envía inicialmente en inglés. Si no es tu primer idioma, indícalo: hablaremos de traducción y publicaremos también en tu idioma cuando podamos. La revisión se realiza en inglés; publicar en otro idioma depende de la capacidad de traducción y revisión.","What belongs here":"Qué temas tienen cabida","Belonging, mutual aid, organizing and collective well-being; human behavior, relationships and person-in-environment perspectives; development across the life course.":"Pertenencia, ayuda mutua, organización y bienestar colectivo; conducta humana, relaciones y perspectivas de la persona en su entorno; desarrollo a lo largo de la vida.","Social welfare systems, public benefits, poverty, housing, employment and education; foundations of social work practice, ethics and engagement with individuals, families, groups and communities.":"Sistemas de bienestar social, prestaciones públicas, pobreza, vivienda, empleo y educación; fundamentos de la práctica del trabajo social, ética y vinculación con personas, familias, grupos y comunidades.","Race, racism, inequality, discrimination and structural injustice; Indigenous communities, sovereignty and self-determination; human rights, environmental justice and equitable access; mental health, voluntary community care, decriminalization and alternatives to incarceration; LGBTQ+ inclusion, disability, aging, HIV/AIDS-related inequities, substance-use policy, recovery, veterans and access to justice.":"Raza, racismo, desigualdad, discriminación e injusticia estructural; pueblos indígenas, soberanía y autodeterminación; derechos humanos, justicia ambiental y acceso equitativo; salud mental, atención comunitaria voluntaria, despenalización y alternativas al encarcelamiento; inclusión LGBTQ+, discapacidad, envejecimiento, inequidades relacionadas con VIH/sida, políticas sobre sustancias, recuperación, veteranos y acceso a la justicia.","Interdisciplinary and international perspectives are welcome when their relevance is explained. Work should connect clearly to Allyspan’s mission.":"Son bienvenidas las perspectivas interdisciplinarias e internacionales cuando se explica su pertinencia. El trabajo debe vincularse claramente con la misión de Allyspan.","Our editorial position":"Nuestra posición editorial","We value dignity, self-determination, accessibility, anti-discrimination and honest inquiry. Critical analysis and respectful disagreement are welcome, including criticism of Allyspan. We distinguish evidence, interpretation and personal experience. Academic rigor should make an argument clearer, not harder to understand.":"Valoramos dignidad, autodeterminación, accesibilidad, no discriminación e investigación honesta. Acogemos análisis críticos y desacuerdos respetuosos, incluso críticas a Allyspan. Distinguimos evidencia, interpretación y experiencia personal. El rigor académico debe aclarar los argumentos, no dificultar su comprensión.","An editor reads your piece and checks that the submission is complete. We aim to respond within 15 business days and will communicate significant delays.":"Un editor lee el trabajo y comprueba que el envío esté completo. Procuramos responder en 15 días hábiles y avisaremos de retrasos importantes.","Research articles require independent methodological review. Formal peer review requires at least two independent qualified reviewers whose identities are confidential to authors. We hold research submissions when qualified review is unavailable.":"Los artículos de investigación requieren revisión metodológica independiente. La revisión formal por pares exige al menos dos revisores independientes cualificados, cuyas identidades son confidenciales para los autores. Si no hay revisión cualificada, el envío queda en espera.","We publish after final author approval, with the article type and actual review status stated.":"Publicamos tras la aprobación final del autor, indicando el tipo de artículo y su estado real de revisión.","This guide sets the contributor and editorial standards for The Allyspan Journal. Choose a section to explore the requirements before preparing your work.":"Esta guía establece las normas para colaboradores y editores de The Allyspan Journal. Elige una sección y consulta los requisitos antes de preparar tu trabajo.","Next: Choose your format":"Siguiente: Elige tu formato","What we publish":"Qué publicamos","Formats and manuscript lengths":"Formatos y extensión de los manuscritos","Word counts exclude references, tables and figure captions. Abstracts count separately. Editors may approve exceptions when justified; length alone never demonstrates rigor.":"El recuento excluye referencias, tablas y pies de figuras. Los resúmenes académicos se cuentan aparte. Los editores pueden autorizar excepciones justificadas; la extensión por sí sola nunca demuestra rigor.","Research Article | 2,500-5,000 words":"Artículo de investigación | 2500-5000 palabras","Original quantitative, qualitative or mixed-methods work. Include a 150-250-word abstract; introduction and question; methods; results; discussion; limitations; ethics statement; funding/conflict disclosures; and references. Report sampling, measures or interview approach, analysis, relevant uncertainty and the basis for conclusions. Human-participant work requires the documentation described in Ethics & responsibility. Methodological expertise must be available before acceptance.":"Trabajo original cuantitativo, cualitativo o de métodos mixtos. Incluye resumen de 150-250 palabras; introducción y pregunta; métodos; resultados; discusión; limitaciones; declaración ética; financiación y conflictos; y referencias. Describe muestreo, medidas o entrevistas, análisis, incertidumbre y fundamento de las conclusiones. Los estudios con participantes humanos requieren la documentación de Ética y responsabilidad. Debe haber experiencia metodológica disponible antes de aceptar.","Literature or Evidence Review | 2,000-4,000 words":"Revisión bibliográfica o de evidencia | 2000-4000 palabras","Synthesize what is known, disagreements and gaps. Include a 150-200-word abstract, search sources and dates, selection approach, synthesis and limitations. A narrative review must be labeled as such. Use “systematic review” or “meta-analysis” only when the actual methods support that designation; provide search strategies and applicable reporting checklist.":"Sintetiza conocimientos, desacuerdos y vacíos. Incluye resumen de 150-200 palabras, fuentes y fechas de búsqueda, selección, síntesis y limitaciones. Identifica las revisiones narrativas como tales. Usa «revisión sistemática» o «metaanálisis» solo si los métodos lo justifican; aporta estrategias de búsqueda y la lista de reporte aplicable.","Policy Review or Policy Analysis | 1,500-3,000 words":"Revisión o análisis de políticas | 1500-3000 palabras","Identify the jurisdiction, policy instrument, status and as-of date. Explain the problem, affected groups, policy mechanism, evidence, implementation, costs or resource implications, equity effects, alternatives and recommendations. Link to primary legislation, regulations or agency material. Distinguish proposed rules from enacted law and enacted law from implementation.":"Identifica jurisdicción, instrumento, estado y fecha de vigencia de la información. Explica problema, grupos afectados, mecanismo, evidencia, aplicación, costes o recursos, equidad, alternativas y recomendaciones. Enlaza legislación, reglamentos o documentos oficiales originales. Distingue propuestas, leyes aprobadas y su aplicación.","Practice and Community Analysis | 1,200-2,500 words":"Análisis de práctica y comunidad | 1200-2500 palabras","An evidence-informed discussion of service design, access barriers, community initiatives or professional practice. Include context, evidence, practical implications and limitations. Program descriptions must not claim effectiveness without suitable evaluation.":"Debate basado en evidencia sobre diseño de servicios, barreras de acceso, iniciativas comunitarias o práctica profesional. Incluye contexto, evidencia, implicaciones prácticas y limitaciones. No atribuyas eficacia a un programa sin evaluación adecuada.","Student Perspectives / Community Voices | 800-1,500 words":"Perspectivas estudiantiles / Voces comunitarias | 800-1500 palabras","Analytical essays and reflective journals combining experience, reflection and relevant scholarship. Explain the perspective, connect it to broader systems, and identify implications. First-person writing is welcome. Label reflective work clearly; it is not original empirical research. No minimum reference count is imposed, but factual claims require sources.":"Ensayos analíticos y diarios reflexivos que combinan experiencia, reflexión y bibliografía pertinente. Explica la perspectiva, vincúlala con sistemas más amplios e identifica implicaciones. Se admite la primera persona. Identifica la reflexión como tal: no es investigación empírica original. No hay mínimo de referencias, pero las afirmaciones de hecho necesitan fuentes.","Book or Resource Review | 700-1,200 words; Commentary | 600-1,000 words":"Reseña de libro o recurso | 700-1200 palabras; Comentario | 600-1000 palabras","Reviews identify the work, assess its evidence, contribution, limitations and audience, and disclose relationships to its creators. Commentaries make a focused, supported argument and acknowledge counterarguments. Letters responding to published work: 300-600 words with references where relevant.":"Las reseñas identifican la obra, evalúan evidencia, contribución, limitaciones y público, y declaran vínculos con sus creadores. Los comentarios presentan un argumento centrado y fundamentado, reconociendo contraargumentos. Cartas sobre trabajos publicados: 300-600 palabras y referencias pertinentes.","These labels are content categories beneath The Allyspan Journal, not separate journals. Accepted work is published on a rolling basis following review, production and author approval. Any themed collection or submission deadline will be announced separately.":"Estas etiquetas son categorías dentro de The Allyspan Journal, no revistas separadas. Publicamos de forma continua tras revisión, preparación y aprobación del autor. Las colecciones temáticas y los plazos se anunciarán aparte.","Next: Writing & visuals":"Siguiente: Redacción y materiales visuales","Academic writing standards":"Normas de redacción académica","Clear arguments, traceable evidence and accessible presentation":"Argumentos claros, evidencia rastreable y presentación accesible","Argument and structure":"Argumento y estructura","State a focused question, its importance and key definitions. Use clear headings, consider counterevidence and limitations, and draw proportionate conclusions. Explain practical implications where useful. Avoid jargon and unsupported certainty.":"Plantea una pregunta concreta, su importancia y definiciones clave. Usa títulos claros, considera evidencia contraria y limitaciones, y formula conclusiones proporcionadas. Explica implicaciones prácticas cuando sea útil. Evita jerga y certezas sin fundamento.","Sources and citations":"Fuentes y citas","Use APA 7 author-date citations and matching references, with DOI links or stable URLs where available. Verify originals and quotation locators. Cite legal materials using applicable conventions and enough detail to locate the authoritative text.":"Usa citas autor-fecha y referencias correspondientes según APA 7, con DOI o URL estable cuando exista. Verifica originales y localizadores de citas textuales. Cita materiales legales según las convenciones aplicables, con detalle suficiente para localizar el texto autorizado.","Prefer peer-reviewed research for empirical claims and primary official sources for current law, policies and rules. Use current and foundational evidence as appropriate; identify non-peer-reviewed material. News supplies context, not a substitute for stronger evidence. Sources must be sufficient, relevant and balanced.":"Para afirmaciones empíricas, prioriza investigación revisada por pares; para legislación, políticas y reglas vigentes, fuentes oficiales primarias. Usa evidencia actual y fundamental según corresponda e identifica materiales sin revisión por pares. Las noticias dan contexto, pero no sustituyen evidencia más sólida. Las fuentes deben ser suficientes, pertinentes y equilibradas.","Precision and reporting":"Precisión y presentación de resultados","Distinguish correlation from causation and statistical from practical significance. Report design, denominators, effect sizes and uncertainty where relevant; explain conflicting findings and limits. Never invent participants, interviews, quotations, results or references. Label hypothetical examples; fictional exercises are not completed research.":"Distingue correlación de causalidad y significación estadística de importancia práctica. Informa diseño, denominadores, tamaños de efecto e incertidumbre cuando corresponda; explica discrepancias y límites. Nunca inventes participantes, entrevistas, citas, resultados o referencias. Identifica ejemplos hipotéticos: los ejercicios ficticios no son investigación realizada.","Respectful language and accessibility":"Lenguaje respetuoso y accesibilidad","Use respectful, accurate language, explain abbreviations and recognize differences within communities. Research, evidence reviews, policy and practice analyses need a 75-125-word plain-language summary; reflective pieces need a 40-75-word introduction.":"Usa lenguaje respetuoso y preciso, explica abreviaturas y reconoce diferencias dentro de las comunidades. Investigación, revisiones de evidencia y análisis de políticas o práctica requieren un resumen claro de 75-125 palabras; las reflexiones, una introducción de 40-75 palabras.","Illustrations and visual materials":"Ilustraciones y materiales visuales","Authors may propose photographs, illustrations, charts, tables and other visuals. Identify sources and ownership or publication permissions; provide captions and descriptive alt text. The Editorial Team may accept, request changes to, replace or decline visuals based on relevance, accuracy, accessibility, privacy, quality and Allyspan’s design standards. Allyspan may propose additional illustrations. Substantive visuals and changes affecting interpretation require author approval before publication.":"Puedes proponer fotografías, ilustraciones, gráficos, tablas y otros materiales. Identifica fuentes, propiedad o permisos de publicación y añade pies y texto alternativo descriptivo. El equipo editorial puede aceptar, pedir cambios, sustituir o rechazar materiales por pertinencia, precisión, accesibilidad, privacidad, calidad o diseño. Allyspan puede proponer ilustraciones adicionales. Los materiales sustantivos y cambios que afecten la interpretación requieren aprobación del autor antes de publicar.","Decorative illustrations must not imply that they show actual participants, clients or documented events. Disclose AI-generated or substantially altered visuals and label them where needed. Authors verify data, scales, labels and any changes to research figures. Provide editable tables and source notes; do not rely on color alone. The Editorial Team makes publication decisions; the design lead approves visual consistency, composition, colors and design quality without overriding accuracy.":"Las ilustraciones decorativas no deben sugerir que muestran participantes, usuarios o hechos reales documentados. Declara las imágenes generadas con IA o muy modificadas y etiquétalas cuando proceda. Verifica datos, escalas, rótulos y cambios en figuras de investigación. Entrega tablas editables y notas de fuente; no dependas solo del color. El equipo editorial decide la publicación; la dirección de diseño aprueba coherencia visual, composición, colores y calidad sin anteponerlos a la precisión.","Translations and research reporting":"Traducciones y presentación de investigación","Translations must identify the original work, translator, permissions and review method; prior agreement and a competent reviewer are required. Submit initially in English. If English isn't your first language, tell us when you submit - we'll discuss translation, and we publish in your language too where we can. Review takes place in English; publication in another language depends on translation and review capacity. Research must follow applicable APA reporting standards and requested discipline-specific guidance; no APA endorsement is implied.":"Las traducciones deben identificar obra original, traductor, permisos y método de revisión; requieren acuerdo previo y revisor competente. Envía inicialmente en inglés. Si no es tu primer idioma, indícalo: hablaremos de traducción y publicaremos también en tu idioma cuando podamos. La revisión se realiza en inglés; otros idiomas dependen de la capacidad de traducción y revisión. La investigación debe seguir las normas de reporte APA aplicables y las orientaciones de la disciplina solicitadas; no se implica respaldo de APA.","Next: Ethics & responsibility":"Siguiente: Ética y responsabilidad","Ethics and author responsibility":"Ética y responsabilidad de autoría","Protect people and preserve the integrity of the record":"Proteger a las personas y preservar la integridad del registro","Originality, authorship and student work":"Originalidad, autoría y trabajos estudiantiles","Submit original work and disclose prior public versions, preprints, theses and substantially overlapping publications. No simultaneous journal submission without prior agreement. All listed authors must make a substantive contribution, approve the final version and accept responsibility for their work. Provide contributor roles and acknowledge other assistance with permission. No honorary authorship or purchased papers.":"Envía trabajo original y declara versiones públicas previas, preprints, tesis y publicaciones con solapamiento sustancial. No lo envíes simultáneamente a otra revista sin acuerdo previo. Todos los autores deben contribuir sustancialmente, aprobar la versión final y asumir responsabilidad. Indica funciones y reconoce otras ayudas con permiso. No se admite autoría honoraria ni trabajos comprados.","A class paper may be adapted if the author has the right to publish it and any course, university, placement or sponsor restrictions are satisfied. A grade or instructor approval is not journal acceptance. Remove course cover pages and disclose class-project origins. Do not imply university, employer or practicum-site endorsement from an author’s affiliation.":"Un trabajo de clase puede adaptarse si el autor tiene derecho a publicarlo y cumple las restricciones del curso, universidad, prácticas o patrocinador. Una nota o la aprobación docente no equivale a aceptación editorial. Retira las portadas académicas y declara su origen. La afiliación no debe sugerir respaldo universitario, laboral o del lugar de prácticas.","Human participants, consent and confidentiality":"Participantes humanos, consentimiento y confidencialidad","Before collecting data, authors must obtain any required institutional ethics review, approval or formal exemption determination. At submission, state the reviewing body, determination, reference number when available and consent approach. Where review was not required, explain why and who made that determination. Editorial review cannot retroactively replace required ethics approval. The applicability of research rules depends on the activity, institution and jurisdiction.":"Antes de recopilar datos, obtén la revisión ética institucional, aprobación o determinación formal de exención que corresponda. Al enviar, indica órgano revisor, decisión, referencia disponible y consentimiento. Si no se exigía revisión, explica por qué y quién lo decidió. La revisión editorial no sustituye retroactivamente una aprobación ética necesaria. Las reglas dependen de la actividad, institución y jurisdicción.","Do not submit client records, identifying school or placement information, private messages or recognizable case histories without a lawful basis, required permissions and editorial clearance. Changing a name alone may not prevent identification. Research participation consent is not automatically consent to public publication of an identifiable story or image. No sensitive source documents or signed consent forms should be sent through ordinary submission email; editors will arrange a secure process if necessary.":"No envíes registros de usuarios, datos identificativos de escuelas o prácticas, mensajes privados ni casos reconocibles sin base legal, permisos y autorización editorial. Cambiar un nombre puede no evitar la identificación. El consentimiento para investigar no autoriza automáticamente publicar una historia o imagen identificable. No envíes documentos sensibles ni consentimientos firmados por correo ordinario; si hace falta, se organizará un proceso seguro.","Conflicts and funding":"Conflictos y financiación","Disclose financial and nonfinancial interests, funding, employment, advocacy roles, relevant personal relationships and the sponsor’s role. A disclosed interest does not automatically disqualify a submission. Reviewers and editors must disclose conflicts and recuse where impartial review cannot be maintained. Authors may describe positionality when relevant without being required to disclose sensitive personal identities.":"Declara intereses financieros y no financieros, financiación, empleo, funciones de defensa, relaciones personales pertinentes y papel del patrocinador. Un interés declarado no descalifica automáticamente. Revisores y editores deben declarar conflictos y abstenerse si no pueden ser imparciales. Puedes explicar tu posicionamiento cuando sea pertinente sin revelar identidades personales sensibles.","Artificial intelligence":"Inteligencia artificial","Authors remain accountable for all content. AI cannot be an author. Disclose generative AI use for drafting, translation, analysis, coding or image creation, naming the tool/version when known, purpose and human verification. Routine spelling correction need not be disclosed unless it materially rewrites content. Fabricated citations and synthetic data passed off as real are prohibited. Do not upload private participant information or confidential manuscripts to AI tools without authorization and adequate safeguards. Editors and reviewers need explicit author permission before external AI processing that cannot assure confidentiality.":"Los autores responden por todo el contenido. La IA no puede ser autora. Declara IA generativa para redacción, traducción, análisis, programación o imágenes: herramienta y versión conocidas, propósito y verificación humana. La corrección ortográfica rutinaria no requiere declaración salvo reescritura sustancial. Se prohíben citas inventadas o datos sintéticos presentados como reales. No subas datos privados ni manuscritos confidenciales a IA sin autorización y garantías adecuadas. Editores y revisores necesitan permiso explícito del autor para procesamiento externo con IA que no garantice confidencialidad.","Criticism must address verifiable conduct, ideas or evidence. Unsupported allegations, plagiarism, discriminatory attacks, dangerous misinformation and promotional material disguised as scholarship are grounds for rejection or further review.":"La crítica debe tratar conductas, ideas o evidencias verificables. Alegaciones sin fundamento, plagio, ataques discriminatorios, desinformación peligrosa y publicidad disfrazada de investigación pueden motivar rechazo o revisión adicional.","Next: Prepare your submission":"Siguiente: Prepara tu envío","How to submit":"Cómo enviar","One complete submission package":"Un paquete de envío completo","Submissions are open":"Los envíos están abiertos","Prepare your complete submission, then choose Submit Your Work below Checklist & resources. Your work is sent privately for editorial review. Nothing is published automatically.":"Prepara tu envío completo y elige Envía tu trabajo debajo de Lista de verificación y recursos. Tu trabajo se envía de forma privada para revisión editorial. Nada se publica automáticamente.","Manuscript file":"Archivo del manuscrito","Submit an editable DOCX, DOC, Pages, TXT, RTF or ODT file; a PDF may accompany it but does not replace the editable manuscript. Use 12-point readable type, double spacing, one-inch margins, page numbers and consistent headings. Include title, article type, abstract where required, plain-language summary or introduction, 4-6 keywords, main text and references. Place tables after the references and provide figures separately with captions and alt text.":"Envía DOCX, DOC, Pages, TXT, RTF u ODT editable; el PDF puede acompañarlo, no sustituirlo. Usa letra legible de 12 puntos, doble espacio, márgenes de una pulgada, páginas numeradas y títulos coherentes. Incluye título, tipo, resumen académico si se exige, resumen claro o introducción, 4-6 palabras clave, texto y referencias. Coloca tablas después de las referencias y figuras aparte, con pies y texto alternativo.","Separate title page and cover note":"Portada y nota de presentación separadas","Provide each author’s publication name, accurate role or affiliation, a 50-80-word biography, contributor roles and the corresponding author’s private email. ORCID is optional. State the word count and article type. Summarize the contribution and fit with Allyspan, disclose prior dissemination and related work, and list funding, conflicts, AI use and ethics/permission status. Do not provide a home address, student ID or unnecessary personal data.":"Indica el nombre de publicación de cada autor, cargo o afiliación precisos, biografía de 50-80 palabras, funciones y correo privado del autor de correspondencia. ORCID es opcional. Indica extensión y tipo de artículo. Resume contribución y afinidad con Allyspan, difusión previa y trabajos relacionados; declara financiación, conflictos, IA y situación ética y de permisos. No incluyas domicilio, identificación estudiantil ni datos innecesarios.","For an external review, editors may request an anonymized manuscript and separate identifying materials. Anonymity cannot always be guaranteed, particularly for first-person narratives or public preprints. Explain requests for a public pseudonym in advance; editors must privately verify the author and agree on accountability and safety arrangements.":"Para revisión externa, pueden pedir un manuscrito anonimizado e información identificativa aparte. No siempre puede garantizarse anonimato, sobre todo en relatos personales o preprints públicos. Explica antes las solicitudes de seudónimo; los editores verificarán privadamente al autor y acordarán responsabilidad y seguridad.","Submission route and author declarations":"Vía de envío y declaraciones de autoría","Use the Journal’s private submission form to send your complete submission. Do not send manuscripts to guessed addresses or post them as comments. The receipt message must identify the policy version and confirm that submission is not acceptance.":"Usa el formulario privado de la revista para enviar el paquete completo. No envíes manuscritos a direcciones supuestas ni los publiques como comentarios. El recibo debe identificar la versión de la política y confirmar que enviar no significa aceptación.","The corresponding author must affirm that all authors agree to submission; the work is accurate and original; required disclosures and permissions are complete; no confidential information is included improperly; and the manuscript is not under review elsewhere unless expressly agreed. Submission grants permission for confidential editorial assessment only. Publication requires separate written author acceptance of the final version and publication terms.":"El autor de correspondencia debe confirmar el acuerdo de todos los autores; precisión y originalidad; declaraciones y permisos completos; ausencia de información confidencial incluida indebidamente; y que no se revisa en otra revista salvo acuerdo expreso. Enviar autoriza solo evaluación editorial confidencial. Publicar requiere aceptación escrita separada de la versión final y las condiciones.","Fees, payment and withdrawal":"Tarifas, pagos y retirada","There is no submission or publication fee and no guaranteed author payment. Any commissioned payment must be agreed in writing in advance and must not purchase acceptance. Disclose any future fees before submission; never introduce a surprise acceptance charge. Authors may withdraw before publication by written request from the corresponding author with coauthor agreement. Resolve author disputes before release.":"No cobramos por envío ni publicación y no garantizamos pago al autor. Cualquier encargo remunerado debe acordarse por escrito antes y nunca comprar aceptación. Las tarifas futuras se informarán antes del envío; no habrá cargos sorpresa al aceptar. Puede retirarse antes de publicar mediante petición escrita del autor de correspondencia con acuerdo de coautores. Resuelve disputas de autoría antes de publicar.","Before you send":"Antes de enviar","Confirm: scope and article type; word count; verified citations; accurate policy dates; limitations; accessible summary; permissions and ethics statement; author approval; conflict/funding/AI disclosures; and a clean editable manuscript. Do not include raw identifiable data. Authors under 18 require a separate safeguarding and permission process before any submission is accepted.":"Comprueba alcance y tipo; extensión; citas verificadas; fechas de políticas; limitaciones; resumen accesible; permisos y ética; aprobación de autoría; financiación, conflictos e IA; y manuscrito editable limpio. No adjuntes datos identificables sin tratar. Menores de 18 años requieren un proceso separado de protección y permisos antes de aceptar cualquier envío.","Next: Editorial review":"Siguiente: Revisión editorial","Editorial review and decisions":"Revisión editorial y decisiones","A rigorous process with honest review labels":"Un proceso riguroso con etiquetas de revisión honestas","Editorial roles":"Funciones editoriales","The Editor-in-Chief is responsible for publication decisions, supported by handling editors and a Community Discussion Editor for moderated responses. Roles may be combined where conflicts are managed. Subject specialists advise on relevant methods or professional issues. Founders, board members, donors and design approvers do not receive automatic publication preference.":"El editor jefe decide la publicación, con apoyo de editores responsables y un editor de Diálogo Comunitario para respuestas moderadas. Las funciones pueden combinarse si se gestionan conflictos. Especialistas asesoran sobre métodos o cuestiones profesionales. Fundadores, directores, donantes y responsables de diseño no tienen preferencia automática para publicar.","Editorial review is not automatically peer review":"La revisión editorial no es automáticamente revisión por pares","Ordinary publications are labeled “Editorial review.” Formal peer review may be offered only when a qualified process is actually available: at least two independent, appropriately qualified reviewers whose identities are confidential to authors, documented reports, conflict checks, author revision and an editorial decision. Describe the review model accurately for each article. Comments and letters do not become peer-reviewed merely because an editor moderates them. Only verified indexing, identifiers and institutional affiliations will be displayed.":"Las publicaciones ordinarias indican «Revisión editorial». Solo hay revisión formal por pares si existe un proceso cualificado: al menos dos revisores independientes adecuados, identidad confidencial para autores, informes documentados, control de conflictos, revisión del autor y decisión editorial. Describe con precisión cada proceso. Moderar comentarios o cartas no los convierte en revisados por pares. Solo se mostrarán indexación, identificadores y afiliaciones verificados.","Reviewer criteria":"Criterios de revisión","Assess a focused question, relevance, accuracy, quality and balance of evidence, sound methods where applicable, transparent limitations, ethical compliance, accessibility and useful implications. Distinguish remediable writing issues from invalid methods or missing ethics approval. Reviewers should explain specific changes respectfully; they must not demand irrelevant citations or use unpublished work for personal advantage.":"Evalúa pregunta concreta, pertinencia, precisión, calidad y equilibrio de evidencia, métodos sólidos cuando corresponda, límites transparentes, ética, accesibilidad e implicaciones útiles. Distingue problemas de escritura corregibles de métodos inválidos o aprobación ética ausente. Pide cambios específicos con respeto; no exijas citas irrelevantes ni uses trabajos inéditos para ventaja personal.","Independence, revisions and appeals":"Independencia, revisiones y apelaciones","A submission by an editor, founder, director or close associate goes to a nonconflicted handling editor; if none is available, postpone review. The author must not control their own acceptance. Send reasoned revision requests and require a point-by-point response. Acceptance and turnaround times are not guaranteed; editors communicate significant delays. Authors may submit one reasoned appeal with evidence of error or unfair process. A noninvolved editor reviews it where possible; if independence cannot be arranged, disclose the limitation.":"Los envíos de editores, fundadores, directores o allegados pasan a un editor sin conflicto; si no hay, se pospone. Nadie controla su propia aceptación. Las peticiones de revisión deben estar razonadas y recibir respuesta punto por punto. No se garantizan aceptación ni plazos; se avisará de demoras importantes. Se admite una apelación razonada con pruebas de error o trato injusto. Un editor no implicado la revisa cuando sea posible; si no hay independencia, se explica esa limitación.","Visual presentation is separate from substantive review. Factual changes require editorial and author review. Editorial decisions are documented with access restricted to authorized personnel.":"La presentación visual es distinta de la revisión sustantiva. Los cambios de hechos requieren revisión editorial y del autor. Las decisiones quedan documentadas con acceso restringido al personal autorizado.","Next: Rights & corrections":"Siguiente: Derechos y correcciones","Publication, rights and corrections":"Publicación, derechos y correcciones","Maintain a trustworthy and transparent public record":"Mantener un registro público fiable y transparente","Author rights and publication permission":"Derechos de autor y permiso de publicación","Authors retain copyright and, through a separate publication agreement, grant Allyspan a nonexclusive license to publish, host, distribute, archive and make agreed formatting/accessibility edits to the accepted work, and use attributed excerpts for Journal promotion. Translation, substantial adaptation or unrelated reuse requires separate agreement. Author-owned work must be distinguished from third-party licensed material. A Creative Commons license is applied only with explicit agreement and a rights check.":"Los autores conservan copyright y, mediante acuerdo separado, otorgan a Allyspan licencia no exclusiva para publicar, alojar, distribuir, archivar, aplicar cambios de formato o accesibilidad acordados y usar extractos atribuidos para promoción. Traducción, adaptación sustancial u otros usos ajenos requieren acuerdo aparte. Distingue obra del autor de materiales de terceros. Una licencia Creative Commons exige acuerdo expreso y verificación de derechos.","What each article displays":"Qué muestra cada artículo","Title; article category; author and accurate affiliation or role; biography; publication and revision dates; actual review label; summary; accessible full text and references; funding, conflicts and material AI disclosures; research ethics statement where relevant; copyright/license information; and a correction/contact route. Add a suggested citation using the stable article URL. Retain version records and readable archives. A DOI or permanent preservation service is not guaranteed; any such arrangement will be identified accurately.":"Título; categoría; autor y cargo o afiliación precisos; biografía; fechas de publicación y revisión; etiqueta real de revisión; resumen; texto completo y referencias accesibles; financiación, conflictos e IA relevante; ética si procede; copyright o licencia; y vía de corrección o contacto. Añade cita sugerida con URL estable. Conserva versiones y archivos legibles. No se garantiza DOI ni preservación permanente; cualquier acuerdo se identificará con precisión.","Editorial independence and reader notice":"Independencia editorial y aviso al lector","Views expressed are the authors’ and do not necessarily represent Allyspan or an affiliated institution. Publication is educational and does not establish a professional relationship or provide individual medical, mental health or legal advice. Journal activity must not be presented as authorization for Allyspan to deliver regulated services. Clearly separate research, opinion, sponsored content and organizational announcements. Journal policy prohibits candidate endorsements or opposition in Journal content published on Allyspan’s behalf; nonpartisan policy analysis remains welcome.":"Las opiniones son de los autores y no representan necesariamente a Allyspan o instituciones afiliadas. Publicar tiene fines educativos, no crea relación profesional ni ofrece consejo individual médico, psicológico o legal. La revista no autoriza servicios regulados de Allyspan. Distingue investigación, opinión, patrocinio y anuncios institucionales. Se prohíbe apoyar u oponerse a candidaturas en contenido de la revista publicado en nombre de Allyspan; se admite análisis de políticas no partidista.","Corrections and integrity concerns":"Correcciones e inquietudes de integridad","Authors must promptly report material errors. Readers may privately report concerns through the designated editorial contact, identifying the article, issue and evidence. An uninvolved editor evaluates concerns where possible, seeks an author response and documents the decision. Do not promise absolute confidentiality or retaliate against good-faith reports.":"Los autores deben avisar pronto de errores importantes. Los lectores pueden informar de forma privada al contacto editorial, indicando artículo, problema y evidencia. Cuando sea posible, un editor no implicado evalúa, solicita respuesta del autor y documenta la decisión. No se promete confidencialidad absoluta ni se permiten represalias contra informes de buena fe.","Fix harmless typographical errors without changing meaning. Publish a dated correction for substantive changes and link it to the article. Use an expression of concern when a serious issue remains unresolved and readers need notice. Retract unreliable or seriously unethical work with a reasoned, linked notice; preserve the scholarly record where safe and lawful. Remove identifying or unlawful material when necessary, documenting the action without repeating harmful content. Offer an appeal route.":"Corrige erratas inocuas sin alterar el sentido. Para cambios sustantivos, publica una corrección fechada vinculada al artículo. Emite una expresión de preocupación si un problema grave sigue sin resolverse y los lectores necesitan aviso. Retracta trabajos poco fiables o gravemente contrarios a la ética con aviso razonado y enlazado; conserva el registro cuando sea seguro y legal. Retira datos identificativos o ilícitos si hace falta, documentando sin repetir contenido dañino. Ofrece apelación.","The submission page provides the applicable privacy notice, retention information and contact route. Unpublished submissions are accessible only to authorized editorial personnel, reviewers and necessary service providers under appropriate safeguards. Private reviewer correspondence is not published without permission. Deletion requests are considered subject to legitimate recordkeeping requirements; authors should review the notice before submitting.":"La página de envío incluye aviso de privacidad, conservación y contacto aplicables. Solo acceden a inéditos el personal autorizado, los revisores y proveedores necesarios, con garantías adecuadas. La correspondencia privada de revisión no se publica sin permiso. Las solicitudes de eliminación están sujetas a necesidades legítimas de registro; revisa el aviso antes de enviar.","Next: Community discussion":"Siguiente: Diálogo comunitario","Community Discussion":"Diálogo Comunitario","Voices, questions and respectful disagreement":"Voces, preguntas y desacuerdos respetuosos","“Share a question, perspective or evidence-informed response. Comments appear only after editorial review.” These standards apply wherever Community Discussion is enabled. A comment form may not be available on every article.":"«Comparte una pregunta, perspectiva o respuesta basada en evidencia. Los comentarios aparecen solo después de revisión editorial». Estas normas se aplican donde esté habilitado el Diálogo Comunitario. No todos los artículos tienen formulario de comentarios.","Participation standards":"Normas de participación","Suggested limit: 50-400 words per comment, with up to 3 relevant links. Respond to the article or an idea it raises; distinguish personal experience from general claims. Cite a reliable source for disputed factual assertions when feasible. Readers need not write an academic essay or disclose a personal diagnosis, service history or identity. Respectful disagreement and criticism of Allyspan are welcome.":"Extensión sugerida: 50-400 palabras y hasta 3 enlaces pertinentes. Responde al artículo o sus ideas; distingue experiencia personal de afirmaciones generales. Aporta fuentes fiables para hechos discutidos cuando sea posible. No hace falta un ensayo académico ni revelar diagnóstico, historial de servicios o identidad. Son bienvenidos el desacuerdo respetuoso y la crítica a Allyspan.","What will not be published":"Qué no se publicará","Threats, harassment, hate speech, identifying client or participant information, doxxing, spam, commercial solicitation, impersonation, plagiarism, unsupported accusations about identifiable people, instructions for harm, or dangerous professional advice. Do not include self-harm methods or graphic detail. Do not treat comments as a confidential service request or emergency-support channel.":"Amenazas, acoso, odio, datos que identifiquen usuarios o participantes, divulgación de datos personales, spam, promoción comercial, suplantación, plagio, acusaciones infundadas sobre personas identificables, instrucciones para causar daño o consejos profesionales peligrosos. No incluyas métodos de autolesión ni detalles gráficos. Los comentarios no son un canal confidencial de servicios ni de ayuda urgente.","Premoderation by the Editorial Team":"Moderación previa por el equipo editorial","Every comment stays private until approved by a trained moderator. Apply the same published rules across viewpoints. Decisions: approve, request revision, decline, or escalate to the handling editor. Do not reject a relevant comment merely because it challenges the article or organization. Permit only light spelling/format edits without changing meaning; obtain consent for substantive edits. Disclose an author/editor’s relevant connection when responding.":"Cada comentario sigue privado hasta que lo apruebe un moderador capacitado. Aplica las mismas reglas a todas las perspectivas. Decisiones: aprobar, pedir cambios, rechazar o escalar al editor. No rechaces un comentario pertinente solo por cuestionar el artículo o la organización. Solo se permiten retoques de ortografía o formato sin cambiar el sentido; los cambios sustantivos requieren consentimiento. Declara vínculos pertinentes de autor o editor al responder.","Moderators may close a thread, pause publication or remove a comment for a documented policy violation or safety concern. Give a brief reason where practicable and offer one request for reconsideration by another editor when available. No guaranteed response time. Remove spam or clear privacy risks promptly; do not publicly repeat the harmful details.":"Los moderadores pueden cerrar debates, pausar publicación o retirar comentarios por infracción documentada o riesgo de seguridad. Da una breve razón cuando sea viable y permite una solicitud de reconsideración por otro editor si está disponible. No hay plazo de respuesta garantizado. Retira pronto spam y riesgos claros de privacidad sin repetir públicamente los detalles dañinos.","Privacy and publication consent":"Privacidad y consentimiento para publicar","Collect a display name and private email for verification; publish only the agreed display name. Allow a pseudonym under consistent moderation rules. Never display an email or IP address. Minimize logs and follow the published retention notice. Before submission, obtain agreement to the comment rules and permission to display the approved comment under the chosen name. Explain that public comments may be copied by others; do not promise complete removal from the internet.":"Recoge un nombre visible y correo privado para verificación; publica solo el nombre acordado. Permite seudónimos con reglas uniformes. Nunca muestres correo o IP. Minimiza registros y sigue el aviso de conservación. Antes de enviar, obtén acuerdo con las reglas y permiso para mostrar el comentario aprobado bajo el nombre elegido. Explica que terceros pueden copiar comentarios públicos; no prometas borrado total de internet.","Comments are not evidence certification":"Los comentarios no certifican la evidencia","Approval means the comment passed moderation, not that Allyspan endorses or independently verifies every statement. Editors may request sources or a formal letter to the editor for substantial critiques. Add a visible notice that the discussion is not continuously monitored and is not a route for urgent or individualized assistance.":"La aprobación solo significa que el comentario pasó la moderación, no que Allyspan respalde o verifique cada afirmación. Para críticas sustantivas, se pueden pedir fuentes o una carta formal al editor. Debe avisarse que la discusión no se supervisa continuamente ni es una vía de asistencia urgente o individualizada.","Next: Checklist & resources":"Siguiente: Lista de verificación y recursos","Contributor checklist and resources":"Lista de verificación y recursos para colaboradores","A final check before submission":"Una última revisión antes de enviar","Manuscript checklist":"Lista del manuscrito","Check the article category and word limit. Include a clear argument, required abstract and summary, 4-6 keywords, headings and APA 7 references. Verify citations, quotations, statistics and policy dates. Explain limitations; distinguish evidence, interpretation and experience.":"Comprueba categoría y extensión. Incluye argumento claro, resúmenes requeridos, 4-6 palabras clave, títulos y referencias APA 7. Verifica citas, citas textuales, estadísticas y fechas de políticas. Explica limitaciones y distingue evidencia, interpretación y experiencia.","Author and ethics checklist":"Lista de autoría y ética","Confirm all authors’ contributions and approval; accurate roles and affiliations; corresponding-author contact; disclosure of funding, conflicts, prior versions and material AI use; research ethics documentation where applicable; consent and permissions for identifiable stories or third-party material; and no confidential client, student or participant records in the submission.":"Confirma contribuciones y aprobación de todos; cargos y afiliaciones precisos; contacto del autor de correspondencia; financiación, conflictos, versiones previas e IA relevante; documentación ética aplicable; consentimiento y permisos para historias identificables o materiales de terceros; y ausencia de registros confidenciales de usuarios, estudiantes o participantes.","Files and permissions":"Archivos y permisos","Provide an editable manuscript, separate title page and cover note, editable tables, figure files with source/permission information and alt text. Do not send signed consent forms or sensitive raw data through ordinary email. A separate publication agreement and approval of the final proof are required before publication. No submission or publication fee is charged.":"Entrega manuscrito editable, portada y nota separadas, tablas editables y figuras con fuentes, permisos y texto alternativo. No envíes consentimientos firmados ni datos sensibles sin tratar por correo ordinario. Antes de publicar, se exige acuerdo separado y aprobación de la prueba final. No hay tarifa de envío ni publicación.","Contact and decision routes":"Contacto y vías de decisión","Use the official submission form or editorial email displayed on the Journal website when submissions are open. For an appeal, correction, privacy concern or integrity report, use the designated editorial contact and identify the article or submission. Include a concise explanation and supporting evidence without unnecessary personal information. Do not post confidential complaints in public comments.":"Cuando se abran los envíos, usa el formulario o correo editorial oficiales del sitio. Para apelaciones, correcciones, privacidad o integridad, contacta a la dirección designada e identifica artículo o envío. Explica brevemente con pruebas sin información personal innecesaria. No publiques quejas confidenciales en comentarios públicos.","Reference framework":"Marco de referencia","These are Allyspan’s own editorial policies, informed by the resources below. They do not imply membership, accreditation, endorsement or certification by these organizations.":"Estas son políticas editoriales propias de Allyspan, orientadas por los recursos siguientes. No implican membresía, acreditación, respaldo ni certificación de esas organizaciones.","APA Style. Style and grammar guidelines; Journal Article Reporting Standards.":"APA Style. Directrices de estilo y gramática; normas para informar artículos de revista.","https://apastyle.apa.org/style-grammar-guidelines":"https://apastyle.apa.org/style-grammar-guidelines","https://apastyle.apa.org/jars":"https://apastyle.apa.org/jars","COPE, DOAJ, OASPA and WAME. Principles of Transparency and Best Practice in Scholarly Publishing.":"COPE, DOAJ, OASPA y WAME. Principios de transparencia y buenas prácticas en publicación académica.","https://doi.org/10.24318/cope.2019.1.12":"https://doi.org/10.24318/cope.2019.1.12","ICMJE. Use of Artificial Intelligence in Publishing.":"ICMJE. Uso de inteligencia artificial en publicaciones.","https://www.icmje.org/recommendations/browse/artificial-intelligence/":"https://www.icmje.org/recommendations/browse/artificial-intelligence/","U.S. HHS, Office for Human Research Protections. Human Subject Regulations Decision Charts: 2018 Requirements.":"HHS de EE. UU., Oficina para la Protección de Investigaciones con Seres Humanos. Diagramas de decisión: requisitos de 2018.","https://www.hhs.gov/ohrp/regulations-and-policy/decision-charts-2018/index.html":"https://www.hhs.gov/ohrp/regulations-and-policy/decision-charts-2018/index.html","Version and future changes":"Versión y cambios futuros","Version 1.1 | October 17, 2026. This edition adds the illustration policy to the baseline public contributor manual. Future substantive revisions will carry a new version and date. New requirements apply prospectively unless ethics, law or safety require immediate action; affected contributors will be informed. Visual branding changes do not alter editorial requirements.":"Versión 1.1 | 17 de octubre de 2026. Añade la política de ilustraciones a la guía pública base. Las futuras revisiones sustantivas tendrán nueva versión y fecha. Las nuevas exigencias se aplican hacia adelante salvo urgencia ética, legal o de seguridad; se informará a quienes afecten. Los cambios de identidad visual no alteran requisitos editoriales.","Return to submission guidance":"Volver a las instrucciones de envío","Change language":"Cambiar idioma","Language":"Idioma","Cancel":"Cancelar","Confirm":"Confirmar","Close":"Cerrar","Languages":"Idiomas","Search Allyspan":"Buscar en Allyspan","Search the Allyspan website":"Buscar en el sitio de Allyspan","Main navigation":"Navegación principal","Allyspan home":"Inicio de Allyspan","No matching pages found":"No se encontraron páginas","This article is currently available in English. Translations will be added after review.":"Este artículo está disponible por ahora en inglés. Añadiremos traducciones después de su revisión.","English article":"Artículo en inglés","English is the original version. If wording differs, please consult the English text.":"El inglés es la versión original. Si hay diferencias de redacción, consulta el texto en inglés.","Changing language will clear the unfinished form. Continue?":"Cambiar el idioma borrará el formulario sin terminar. ¿Continuar?","Paste a link first.":"Pega un enlace primero.","That link doesn’t look complete. Check it and try again.":"El enlace parece incompleto. Revísalo e inténtalo de nuevo.","Please use a website link that starts with http:// or https://.":"Usa un enlace que empiece por http:// o https://.","Please enter a complete website address, like example.com.":"Introduce una dirección completa, como example.com.","The QR generator didn’t load. Check your internet connection and try again.":"No se cargó el generador QR. Comprueba tu conexión e inténtalo de nuevo.","Could not create the QR code. Try a shorter link.":"No se pudo crear el QR. Prueba un enlace más corto.","Please use {min}-{max} words.":"Usa entre {min} y {max} palabras.","{n} words":"{n} palabras","{min}-{max} words, following the contributor guide.":"{min}-{max} palabras, según la guía para colaboradores.","Enter 4-6 different keywords, separated by commas.":"Introduce entre 4 y 6 palabras clave distintas, separadas por comas.","Choose a supported file format.":"Elige un formato de archivo admitido."," (optional)":" (opcional)","Caption":"Pie de imagen","Alt text":"Texto alternativo","Source and permission details":"Fuente y detalles de permisos","Coauthor":"Coautor","Publication name":"Nombre para publicación","Role or affiliation":"Cargo o afiliación","Short biography (50-80 words)":"Biografía breve (50-80 palabras)","Please use 50-80 words.":"Usa entre 50 y 80 palabras.","Contribution":"Contribución","Remove coauthor":"Eliminar coautor","Please check the highlighted field before continuing.":"Revisa el campo resaltado antes de continuar.","Article type":"Tipo de artículo","Main topic":"Tema principal","Word count":"Número de palabras","Summary":"Resumen","Manuscript":"Manuscrito","None":"Ninguno","Companion PDF":"PDF complementario","Supporting images":"Imágenes de apoyo","Translation notes":"Notas de traducción","Private email":"Correo privado","Biography":"Biografía","Safety request":"Solicitud de seguridad","Declarations":"Declaraciones","All four declarations confirmed.":"Las cuatro declaraciones están confirmadas.","Attachments must total no more than 10 MB.":"Los adjuntos no deben superar 10 MB en total.","Submissions are temporarily unavailable. Please try again later.":"Los envíos no están disponibles temporalmente. Inténtalo más tarde.","Send your manuscript privately for editorial review. Nothing is published automatically.":"Envía tu manuscrito de forma privada para revisión editorial. Nada se publica automáticamente.","Your manuscript will be sent privately to the Journal. We will email a receipt after delivery.":"Tu manuscrito se enviará de forma privada a la revista. Enviaremos un acuse de recibo por correo tras la entrega.","Questions or withdrawal requests: journal@allyspan.org":"Consultas o solicitudes de retirada: journal@allyspan.org","Required fields are marked *. Do not include confidential participant records.":"Los campos obligatorios se marcan con *. No incluyas registros confidenciales de participantes.","Review your details before sending. Nothing is published automatically.":"Revisa los datos antes de enviar. Nada se publica automáticamente.","The security check could not load. Please try again later.":"No se pudo cargar la comprobación de seguridad. Inténtalo más tarde.","The submission service could not be reached. Please try again later.":"No se pudo contactar con el servicio de envío. Inténtalo más tarde.","Sending...":"Enviando...","We could not confirm delivery. Keep this page open and try again.":"No pudimos confirmar la entrega. Mantén la página abierta e inténtalo de nuevo.","We could not confirm delivery. Please try again.":"No pudimos confirmar la entrega. Inténtalo de nuevo.","Thank you for your submission":"Gracias por tu envío","Your work has been received for editorial review. Nothing has been published.":"Tu trabajo se ha recibido para revisión editorial. No se ha publicado nada.","Your reference: ":"Tu referencia: ","A receipt email has been requested. If it does not arrive, check spam or contact journal@allyspan.org with your reference.":"Se ha solicitado un acuse de recibo. Si no llega, revisa el correo no deseado o escribe a journal@allyspan.org con tu referencia.","We aim to give an initial response within 15 business days of a complete submission.":"Procuramos dar una primera respuesta en 15 días hábiles tras recibir el envío completo.","We could not confirm delivery. Keep the form open and try again.":"No pudimos confirmar la entrega. Mantén el formulario abierto e inténtalo de nuevo.","required":"obligatorio","Submission steps":"Pasos del envío","Submission service status":"Estado del servicio de envío","Your generated QR code":"Tu código QR generado","Allyspan golden tree and sun emblem":"Emblema dorado de árbol y sol de Allyspan","New York City skyline at dusk":"Horizonte de la ciudad de Nueva York al anochecer","Please wait a minute before trying again.":"Espera un minuto antes de intentarlo de nuevo.","Please complete the security check again.":"Completa de nuevo la comprobación de seguridad.","Submissions are not open yet.":"Los envíos aún no están abiertos.","Unable to verify this request.":"No se pudo verificar esta solicitud.","Please reopen the form and try again.":"Vuelve a abrir el formulario e inténtalo de nuevo.","The submission is empty.":"El envío está vacío.","Repeated fields are not supported.":"No se admiten campos repetidos.","Check the article type and manuscript word count.":"Revisa el tipo de artículo y la extensión del manuscrito.","Include 4-6 different keywords.":"Incluye entre 4 y 6 palabras clave distintas.","Enter one valid corresponding author email.":"Introduce un correo válido para el autor de correspondencia.","Choose the manuscript language.":"Elige el idioma del manuscrito.","Complete the research ethics question.":"Completa la pregunta de ética de investigación.","Confirm all four author declarations.":"Confirma las cuatro declaraciones de autoría.","For more than 20 coauthors, contact journal@allyspan.org.":"Si hay más de 20 coautores, contacta con journal@allyspan.org.","Attach one editable manuscript.":"Adjunta un manuscrito editable.","Unsupported or empty attachment.":"Archivo adjunto vacío o no admitido.","Use no more than 20 supporting images.":"No incluyas más de 20 imágenes de apoyo.","An attachment does not match its file format.":"Un adjunto no coincide con su formato de archivo.","TXT manuscripts must be UTF-8 text.":"Los manuscritos TXT deben usar UTF-8.","Your work was received, but we could not confirm your receipt email. Keep this reference and contact journal@allyspan.org if needed.":"Recibimos tu trabajo, pero no pudimos confirmar el correo de recibo. Guarda la referencia y contacta con journal@allyspan.org si hace falta.","We could not confirm delivery. Keep the form open and try again. If you have received a reference by email, contact journal@allyspan.org before resubmitting.":"No pudimos confirmar la entrega. Mantén el formulario abierto e inténtalo de nuevo. Si recibiste una referencia por correo, contacta con journal@allyspan.org antes de volver a enviar.","The summary must contain 100-150 words.":"El resumen debe contener 100-150 palabras.","The biography must contain 50-80 words.":"La biografía debe contener 50-80 palabras.","Each coauthor biography must contain 50-80 words.":"Cada biografía de coautor debe contener 50-80 palabras.","Review and receipt emails currently use English.":"La revisión y los correos de confirmación se realizan actualmente en inglés.","Allyspan — Support That Stays Beside You":"Allyspan - Apoyo que permanece a tu lado","Allyspan. Support That Stays Beside You.":"Allyspan. Apoyo que permanece a tu lado.","More ways to connect":"Más formas de conectar","Contributor links":"Enlaces para colaboradores","New York City skyline across the water at dusk":"Horizonte de Nueva York al otro lado del agua al anochecer","Contributor guide sections":"Secciones de la guía para colaboradores","Journal links":"Enlaces de la revista","Allyspan emblem: a golden sun above a branching tree with an intertwined trunk and stepped foundation":"Emblema de Allyspan: un sol dorado sobre un árbol ramificado, con tronco entrelazado y base escalonada","Allyspan gold tree emblem":"Emblema del árbol dorado de Allyspan","Generated QR code with Allyspan website and tagline beneath":"Código QR generado, con el sitio y el lema de Allyspan debajo","QR code generator":"Generador de códigos QR"},"articleNotes":{"es":"Este artículo está disponible por ahora en inglés. Añadiremos traducciones después de su revisión.","zh-Hans":"本文目前仅提供英文版。译文将在审阅后添加。"},"search":[{"title":"Allyspan","text":"Allyspan","url":"/es/"},{"title":"Allyspan y su logotipo","text":"Allyspan y su logotipo","url":"/es/about/allyspan-and-logo/"},{"title":"Nuestra misión","text":"Nuestra misión","url":"/es/about/our-mission/"},{"title":"Programs and Partnerships","text":"Programs and Partnerships","url":"/es/about/our-support/"},{"title":"Contacto","text":"Contacto","url":"/es/about/connect/"},{"title":"Classroom Studio Guide for Teachers and Learners","text":"Classroom Studio Guide for Teachers and Learners","url":"/es/resources/introduction-to-classroom-studio/"},{"title":"Free QR Code Generator","text":"Free QR Code Generator","url":"/es/resources/qr-studio/"},{"title":"The Allyspan Journal","text":"The Allyspan Journal","url":"/es/showcase/publications/"},{"title":"Cómo publicar tu trabajo","text":"Cómo publicar tu trabajo","url":"/es/showcase/how-to-publish/"},{"title":"Envía tu trabajo","text":"Envía tu trabajo","url":"/es/showcase/submit-your-work/"},{"title":"Submission Privacy","text":"Submission Privacy","url":"/es/showcase/submission-privacy/"}]};
